/** Binary data as base64url without padding. */
typealias Base64Url = String

/** X25519 public key, exactly 32 bytes, base64url without padding. */
typealias PublicKey = String

/** Ed25519 public key of an ADK version (32 bytes, base64url without padding). verify_key(v) is derived from ADK(v) with HKDF-SHA256 info "sa-keyver-sign-v1". */
typealias VerifyKey = String

/** Ed25519 signature (64 bytes, base64url without padding). */
typealias Signature = String

/** Opaque wrapped key (at most 4 KB decoded), base64url without padding. The server cannot unwrap it. */
typealias WrappedBlob = String

