    @SerialName("key_version") val keyVersion: Int? = null,
    /** Signature by ADK(key_version) over "sa-devkey-v1|<device_id>|<key_version>|<b64u(public_key)>"; clients verify it before wrapping to the key. */
    @SerialName("proof") val proof: Signature? = null,
)

