    @SerialName("devices") val devices: List<DeviceKey>,
    /** ADK versions wrapped for the caller by rotations, until acknowledged. */
    @SerialName("pending") val pending: List<PendingBlob>,
    /** True once an added device with a registered wrapping key has left the account (revoke, sign-out, password reset or change, identity reset, refresh-secret reuse, expiry) since the last rotation; a ready client rotates. A successful rotation clears it (docs/ADR/0014-current-version-proofs.md). */
    @SerialName("rotation_due") val rotationDue: Boolean,
)

