    @SerialName("verify_key") val verifyKey: VerifyKey,
    @SerialName("recovery_anchor") val recoveryAnchor: RecoveryAnchor,
    /** Ed25519 by the signing key of ADK(1) over "sa-recoverykey-v1|" + b64u(recovery_public_key); verified with verify_key. */
    @SerialName("recovery_key_signature") val recoveryKeySignature: Signature,
)

