/** HMAC-SHA256(key = HKDF-SHA256(recovery_seed, info "sa-recovery-anchor-v1"), msg = "sa-anchor-v1|" + b64u(verify_key(1))), 32 bytes base64url. Lets a recovery-phrase holder authenticate verify_key(1) without trusting the server. */
typealias RecoveryAnchor = String

