    /** ADK(v-1) wrapped with ADK(v). */
    @SerialName("chain_blob") val chainBlob: WrappedBlob,
    /** Exactly one blob for every other added device whose registered proof is by the current version v (devices with no key or an older proof get none and must pair again); a blob for the caller itself is accepted as a safety copy and delivered through its pending list. */
    @SerialName("device_blobs") val deviceBlobs: List<DeviceBlob>,
    /** verify_key(v+1). */
    @SerialName("verify_key") val verifyKey: VerifyKey,
    /** By the signing key of the current version v over "sa-rotate-v1|" + (v+1) + "|" + b64u(verify_key(v+1)) + "|" + b64u(SHA-256(chain_blob bytes)). */
    @SerialName("signature") val signature: Signature,
)

